-- Bank reconciliation — generated 2026-11-16
--
-- Brings the app's records into line with four CommBank statements covering
-- 1 Jul 2025 to 30 Sep 2026, every row of which was checked against its
-- running balance before any of this was written.
--
-- Run it in Supabase → SQL Editor. TAKE A BACKUP FIRST (Settings → Export
-- backup in the app). Read the verification block at the bottom before you
-- type COMMIT.
--
-- What it does
--   1. Corrects 21 invoice payment dates. A bulk mark-paid on
--      13 Sep 2026 moved a year of FY26 receipts into Q1 FY27, which is why
--      the app reported ~$105k of income in a quarter the bank shows $55k in.
--   2. Marks invoice 091125U superseded. It is the original invoice for job
--      NP-0093, re-issued as 091125P (part) + 131125 (final), and is
--      double-counting $4,850.
--   3. Inserts 294 business costs the app has no record of.
--   4. Adds the work trailer to the asset register.
--
-- Prerequisites — run these first or it will fail:
--   supabase/np-assets.sql
--   supabase/np-expense-business-use.sql
--
-- What it deliberately does NOT do
--   * import the 211 materials purchases already in np_materials — that
--     would double-count $44,233;
--   * import subcontract labour, all of which is already in np_labour;
--   * invent invoices for the 90 FY26 client receipts with no app record.
--
-- Undoing it
--   Every created row has an id starting 'bankrec-2026-11-16-'. To reverse the inserts:
--     delete from np_expenses where id like 'bankrec-2026-11-16-%';
--     delete from np_assets   where id like 'bankrec-2026-11-16-%';
--   The date corrections are listed one per line below, each with the value
--   it replaced, so they can be put back by hand if you ever need to.

begin;

-- ── 1. Invoice payment dates ────────────────────────────────
-- Each UPDATE asserts date_paid is still '2026-09-13'. If you have already
-- corrected one by hand, its statement matches no row and changes nothing.

-- 0059-300726  Cath and Andrew              $ 18,507.50  Direct Credit 123079 Catherine Leonar Exterior Painting
update np_invoices set date_paid = '2026-07-31', notes = coalesce(notes, '') || ' [bank recon 2026-11-16] paid 2026-07-31 per statement'
  where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id = '0059-300726' and date_paid = '2026-09-13';

