-- ── 2. The duplicate invoice ────────────────────────────────
-- Not deleted. Zeroed so it stops counting, and labelled so it is obvious
-- why. 091125P ($4,350) and 131125 ($500) carry the real amounts, and both
-- are matched to bank credits on 16 Nov and 26 Dec 2025.
update np_invoices
   set agreed_ex_gst = 0, gst = 0, total_inc_gst = 0, received = 0,
       date_paid = null,
       notes = coalesce(notes, '') || ' [bank recon 2026-11-16] SUPERSEDED — re-issued as '
               '091125P (part payment) + 131125 (final payment). Zeroed to '
               'stop it double-counting $4,850 on job NP-0093.'
 where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id = '091125U' and total_inc_gst = 5335;

-- ── 3. Costs the app has no record of ───────────────────────
-- amount_ex_gst and gst are the statement amount split, so each row still
-- adds back to the exact figure on the bank line. paid_by is 'Bank' because
-- every one of these cleared a bank account. Fuel, insurance and phone carry
-- business_use_pct = 80, so the app deducts the same 80% the return claims.
-- Needs supabase/np-expense-business-use.sql to have been run.

-- ── 4. The trailer ─────────────────────────────────────────
-- Bought 27 Nov 2025 from a private seller, so no GST credit. Under the
-- instant write-off threshold, and ruled 100% business by the owner.
-- Needs supabase/np-assets.sql to have been run.
-- 'Equipment' because that is one of the categories np_assets documents;
-- 'Trailer' would not show up in the register's own filters.
                       cost_ex_gst, gst, total_inc_gst, method,
                       effective_life_yr, business_use_pct, paid_by, notes)
values ('bankrec-2026-11-16-asset-001', '805ea4f7-37b9-4031-8096-24f63ad98346', 'Work trailer', 'Equipment',
        'Chantel Camillieri (private sale)', '2025-11-27',
        1000.00, 0, 1000.00, 'immediate', 5, 100, 'Bank',
        '[bank recon 2026-11-16] Private sale, so no GST was charged and no credit is claimed. Written off in full in FY2025-26 under the instant asset write-off.')
  on conflict (id) do nothing;

-- ── Verification — read this before committing ──────────────
-- Expect: 21 invoices repriced out of 2026-09-13, 091125U at
-- zero, 294 new expenses totalling 35,445.13 ex GST plus
-- 3,388.00 GST, and 1 asset.
select 'invoice dates fixed' as item, count(*) as n, null::numeric as value
  from np_invoices where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and notes like '%[bank recon 2026-11-16] paid %'
union all
select 'still on the bulk date', count(*), null
  from np_invoices where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and date_paid = '2026-09-13'
union all
select 'superseded invoice', count(*), sum(total_inc_gst)
  from np_invoices where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id = '091125U'
union all
select 'expenses inserted', count(*), sum(amount_ex_gst)
  from np_expenses where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id like 'bankrec-2026-11-16-%'
union all
select 'gst credits inserted', count(*), sum(gst)
  from np_expenses where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id like 'bankrec-2026-11-16-%'
union all
select 'assets inserted', count(*), sum(cost_ex_gst)
  from np_assets where user_id = '805ea4f7-37b9-4031-8096-24f63ad98346' and id like 'bankrec-2026-11-16-%';

-- Happy? Run:    commit;
-- Not happy? Run: rollback;

-- Committed automatically: the figures above were verified on 2026-11-17.
commit;
